/* =============================================================================
   Role-specific interview models (original BSP content).

   ROLE_MODELS[key] = {
     appliesTo:[profession ids] | group:"<group id>",
     comps?:[competency ids]       // replaces the profession's model for interviews + scoring
     weights?:{background,domain,reasoning,ai,communication}  // overrides the type weights
     healthcare?:true               // fictional-scenario safeguards
     questions:[{ stage, type, comp, d, text, sig, fu?:{followUpType:text}, artifact?, lang? }]
     memory:[{ re, comp, q }]       // same-session callbacks: "You mentioned that …"
     final?:{ text, sig }
   }
   stage: domain | reasoning | ai | communication   (background = intro + behavioral)
   artifact kinds: table{title,cols,rows,note} · code{title,code} · doc{title,text}
                   chart{title,unit,bars:[[label,value]]} · compare{items:[[label,text]]}
   ========================================================================== */
"use strict";

/* ---------- Extra competencies used by role models ------------------------ */
C("uncertainty","Managing Uncertainty",
  ["uncertain","reassess","monitor","escalate","differential","limits","safety net","ask","senior","review"],
  "How do you act safely when the information you have is incomplete or ambiguous?",
  "Two plausible explanations fit a fictional patient's symptoms and the test that would separate them takes hours. What do you do in the meantime?",
  "you had to act before you had all the information you wanted");
C("evidence_clin","Evidence-Based Practice",
  ["guideline","evidence","research","protocol","current","source","review","trial","outcome","appraise"],
  "How do you keep your practice aligned with current evidence and guidelines?",
  "A colleague insists on a practice you believe current guidance no longer supports. How do you handle it?",
  "you changed your practice because of new evidence");
C("en_comm","English Communication",
  ["clear","example","because","audience","meaning","context","explain","reader","client","specific"],
  "In English: explain to a client why a word-for-word translation can mislead readers. Give one example.","", "");
C("fr_comm","French Communication",
  ["exemple","parce que","client","contexte","expérience","clair","français","anglais","projet","travail"],
  "En français : décrivez votre expérience professionnelle en français et en anglais. Dans quels contextes utilisez-vous chaque langue ?","", "");
C("comprehension","Comprehension",
  ["main","request","summary","first","detail","client","demande","principal","résumé","d'abord"],
  "How do you make sure you have fully understood a source text before translating or evaluating it?","", "");
C("meaning_pres","Meaning Preservation",
  ["meaning","sens","negation","omission","addition","faithful","fidèle","accurate","source","change"],
  "How do you check that a translation preserves the meaning of the source, not just its words?","", "");
C("grammar_fr","Grammar",
  ["accord","grammaire","verbe","préposition","exemple","orthographe","conjugaison","genre","pluriel","règle"],
  "En français : quelles sont les erreurs de grammaire que vous repérez le plus souvent dans les traductions automatiques ?","", "");
C("tone","Tone",
  ["tone","ton","register","registre","formal","formel","vouvoiement","polite","audience","context"],
  "How do you adapt tone and register when moving between English and French?","", "");
C("translation_judgment","Translation Judgment",
  ["better","natural","faux ami","false friend","meaning","register","source","target","choose","justify"],
  "How do you choose between two acceptable translations of the same sentence?","", "");

