/* Resolve the role model for a profession (direct match first, then group). */
function roleModelFor(p){
  if(!p) return null;
  for(const k in ROLE_MODELS){ const m=ROLE_MODELS[k]; if((m.appliesTo||[]).includes(p.id)) return Object.assign({key:k}, m); }
  for(const k in ROLE_MODELS){ const m=ROLE_MODELS[k]; if(m.group && m.group===p.group) return Object.assign({key:k}, m); }
  return null;
}
